import React from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getVehicleById } from '../utils/vehicleData';
import { useAuth } from '../context/AuthContext';
import './VehicleDetail.css';

export default function VehicleDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();
  const vehicle = getVehicleById(id);

  if (!vehicle) {
    return (
      <main className="page-wrapper" style={{ display:'flex', alignItems:'center', justifyContent:'center', textAlign:'center' }}>
        <div>
          <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 48, color: 'var(--gold)' }}>404</h2>
          <p style={{ color: 'var(--white-muted)', marginTop: 12 }}>Véhicule introuvable</p>
          <Link to="/vehicles" className="btn-gold" style={{ marginTop: 32, display: 'inline-flex' }}>
            <span>Retour aux véhicules</span>
          </Link>
        </div>
      </main>
    );
  }

  return (
    <main className="page-wrapper vd-page">
      {/* Hero */}
      <div className="vd-hero" style={{ background: `linear-gradient(135deg, ${vehicle.color} 0%, #111 100%)` }}>
        <div className="vd-hero__content container">
          <Link to="/vehicles" className="vd-back">← Retour à la collection</Link>
          <span className="section-label">{vehicle.category}</span>
          <h1 className="vd-hero__title">{vehicle.brand}</h1>
          <h2 className="vd-hero__model">{vehicle.model}</h2>
          <p className="vd-hero__tagline">{vehicle.tagline}</p>
        </div>
        {/* Placeholder for image */}
        <div className="vd-hero__visual">
          {/* <img src={`/assets/images/vehicles/${vehicle.id}.jpg`} alt={vehicle.model} /> */}
          <div className="vd-hero__placeholder" style={{ color: vehicle.accent }}>
            <span className="vd-hero__placeholder-brand">{vehicle.brand}</span>
            <span className="vd-hero__placeholder-model">{vehicle.model}</span>
            <span className="vd-hero__placeholder-hint">[ Ajouter l'image dans /assets/images/vehicles/{vehicle.id}.jpg ]</span>
          </div>
        </div>
      </div>

      {/* Details */}
      <section className="vd-details container">
        <div className="vd-specs-bar">
          {[
            { label: 'Puissance', value: vehicle.power },
            { label: '0 à 100', value: vehicle.acceleration },
            { label: 'Vitesse max', value: vehicle.speed },
            { label: 'Énergie', value: vehicle.fuel },
          ].map(s => (
            <div key={s.label} className="vd-spec-item">
              <span className="vd-spec-item__value" style={{ color: vehicle.accent }}>{s.value}</span>
              <span className="vd-spec-item__label">{s.label}</span>
            </div>
          ))}
        </div>

        <div className="vd-body">
          <div className="vd-features">
            <h3 className="vd-section-title">Équipements Clés</h3>
            <div className="vd-features-grid">
              {vehicle.features.map(f => (
                <div key={f} className="vd-feature">
                  <span className="vd-feature__dot" style={{ background: vehicle.accent }} />
                  {f}
                </div>
              ))}
            </div>
          </div>

          <div className="vd-cta-panel">
            <div className="vd-price-block">
              <span className="vd-price-label">Prix de départ</span>
              <span className="vd-price-value">{vehicle.price} €</span>
              <span className="vd-price-note">Financement disponible · LOA · Crédit</span>
            </div>

            {isAuthenticated ? (
              <div className="vd-actions">
                <Link to="/contact" className="btn-gold" style={{ width: '100%', justifyContent: 'center' }}>
                  <span>Demander un essai</span>
                </Link>
                <Link to="/contact" className="btn-white" style={{ width: '100%', justifyContent: 'center', marginTop: 12 }}>
                  <span>Configurer mon véhicule</span>
                </Link>
              </div>
            ) : (
              <div className="vd-auth-prompt">
                <p>Connectez-vous pour accéder à la configuration, l'essai routier et les offres personnalisées.</p>
                <Link to="/login" className="btn-gold" style={{ marginTop: 20, display: 'inline-flex' }}>
                  <span>Se connecter</span>
                </Link>
              </div>
            )}
          </div>
        </div>
      </section>
    </main>
  );
}
